def bash_completion():
    import argparse
    import subprocess

    class CustomArgumentParser(argparse.ArgumentParser):
        def format_help(self):
            return self.prog

    def get_commands():
        result = subprocess.run(['borgmatic', '--help'], capture_output=True, text=True)
        lines = result.stdout.split('\n')
        commands = [line.split()[0] for line in lines if line.startswith('  ') and not line.startswith('  -')]
        return commands

    def get_command_parser(command):
        try:
            result = subprocess.run(['borgmatic', command, '--help'], capture_output=True, text=True)
            parser = CustomArgumentParser(prog=command)
            parser.parse_args(result.stdout.split())
            return parser
        except:
            return None

    commands = get_commands()
    completions = []

    for command in commands:
        parser = get_command_parser(command)
        if parser:
            completions.append(f'complete -W "{parser.format_help()}" {parser.prog}')

    print('\n'.join(completions))

