def validate_version_inventories(self, version_dirs):
    root_inventory = self.load_inventory('root')
    content_digests_diff = {}

    for version in version_dirs:
        version_inventory = self.load_inventory(version)
        if not version_inventory:
            raise ValueError(f"Inventory missing for version: {version}")

        for item, digest in version_inventory.items():
            if item not in root_inventory:
                raise KeyError(f"Item {item} in version {version} not found in root inventory")
            if digest!= root_inventory[item]:
                if item not in content_digests_diff:
                    content_digests_diff[item] = []
                content_digests_diff[item].append((version, digest))

    for item, diffs in content_digests_diff.items():
        if len(set(d[1] for d in diffs)) > 1:
            raise ValueError(f"Inconsistent digests found for item {item}: {diffs}")

    return content_digests_diff

