    values = []

    for bin_ in hist.bins:
        if get_coordinate == "left":
            coord = bin_.left_edge
        elif get_coordinate == "right":
            coord = bin_.right_edge
        elif get_coordinate == "middle":
            coord = (bin_.left_edge + bin_.right_edge) / 2
        else:
            raise ValueError("Invalid get_coordinate value")

        coordinates.append(coord)
        values.append(make_value(bin_.content))

