import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list) or not commands:
        raise ValueError("Commands must be a non-empty list.")

    full_command = commands + args

    stdout = subprocess.PIPE if verbose else subprocess.DEVNULL
    stderr = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL

    try:
        process = subprocess.Popen(full_command, cwd=cwd, stdout=stdout, stderr=stderr, env=env)
        output, error = process.communicate()

        if verbose:
            print(output.decode())

        if process.returncode!= 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=output, stderr=error)

        return output, error

    except FileNotFoundError:
        raise FileNotFoundError(f"Command '{commands[0]}' not found.")

    except subprocess.CalledProcessError as e:
        raise e

    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}")

