    if not all(isinstance(piece, str) for piece in pieces):
        raise ValueError("all elements in pieces must be strings")
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    if style == "uppercase":
        return [piece.upper() for piece in pieces]
    elif style == "lowercase":
        return [piece.lower() for piece in pieces]
    elif style == "capitalize":
        return [piece.capitalize() for piece in pieces]
    else:
        raise ValueError(f"unsupported style: {style}")

