    dt = isoparse(dt_str)
    if dt.utcoffset() == timedelta(0):
        return dt.replace(tzinfo=tzutc())
    elif dt.utcoffset():
        return dt.replace(tzinfo=tzoffset(None, int(dt.utcoffset().total_seconds())))
    return dt

