def fromutc(self, dt):
    fold = (dt.utcoffset()!= dt.replace(fold=not dt.fold).utcoffset())
    return self.localize(dt.replace(tzinfo=None), is_dst=None) if fold else self.localize(dt.replace(tzinfo=None))

