from zope.interface import Interface, providedBy, Invalid
import inspect

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface}")

    required_methods = set(iface.names(all=True))
    required_attributes = set(attr for attr in required_methods if not callable(getattr(iface, attr, None)))
    required_methods -= required_attributes

    candidate_methods = set(name for name, member in inspect.getmembers(candidate, predicate=inspect.ismethod) if not name.startswith('__'))
    candidate_attributes = set(name for name, member in inspect.getmembers(candidate) if not callable(member) and not name.startswith('__'))

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method in missing_methods:
        errors.append(f"Missing method: {method}")

    for attribute in missing_attributes:
        errors.append(f"Missing attribute: {attribute}")

    for method in required_methods.intersection(candidate_methods):
        iface_method = getattr(iface, method)
        candidate_method = getattr(candidate, method)
        iface_signature = inspect.signature(iface_method)
        candidate_signature = inspect.signature(candidate_method)

        if iface_signature!= candidate_signature:
            errors.append(f"Incorrect signature for method {method}: expected {iface_signature}, got {candidate_signature}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

from zope.interface import Interface, providedBy, Invalid
import inspect

def verifyObject(iface, candidate, tentative=False):
    errors = []
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide the interface {iface}")

    required_methods = set(iface.names(all=True))
    candidate_methods = set(dir(candidate))
    missing_methods = required_methods - candidate_methods

    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for method_name in required_methods.intersection(candidate_methods):
        method = getattr(iface, method_name)
        if callable(method):
            iface_signature = inspect.signature(method)
            candidate_method = getattr(candidate, method_name)
            candidate_signature = inspect.signature(candidate_method)
            if iface_signature!= candidate_signature:
                errors.append(f"Incorrect signature for method {method_name}: expected {iface_signature}, got {candidate_signature}")

    required_attributes = [name for name in iface.names(all=True) if not callable(getattr(iface, name))]
    missing_attributes = set(required_attributes) - set(candidate.__dict__.keys())

    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))
    return True

