def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    if k not in cache:
                        cache[k] = func(*args, **kwargs)
                    return cache[k]
            else:
                if k not in cache:
                    cache[k] = func(*args, **kwargs)
                return cache[k]
        return wrapper
    return decorator

