class LFUCache:
    def __init__(self):
        self.cache = {}
        self.freq = defaultdict(list)
        self.keys_freq = {}
        self.min_freq = 0

    def popitem(self):
        k, v = self.freq[self.min_freq].pop(0)
        del self.cache[k]
        del self.keys_freq[k]
        if not self.freq[self.min_freq]:
            del self.freq[self.min_freq]
            self.min_freq += 1
        return k, v

