def point_type(name, fields, srid_map):
    class Point:
        def __init__(self, **kwargs):
            for field in fields:
                setattr(self, field, kwargs.get(field))
            self.srid = srid_map.get(kwargs.get('srid_key'), None)

        def __repr__(self):
            field_values = ', '.join(f'{field}={getattr(self, field)}' for field in fields)
            return f'{name}({field_values}, srid={self.srid})'

    return Point

def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds")
    seconds, nanoseconds = divmod(ticks, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hour=hours, minute=minutes, second=seconds, microsecond=nanoseconds // 1_000, tzinfo=tz)

