def load_configurations(config_filenames, overrides=None, resolve_env=True):
    config_dict = {}
    log_records = []

    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = {k: v.format(**os.environ) if isinstance(v, str) else v for k, v in config.items()}
                if overrides:
                    config.update(overrides)
                config_dict[filename] = config
        except (IOError, OSError) as e:
            record = logging.makeLogRecord({'levelno': logging.ERROR,'msg': f"Cannot read file {filename}: {e}"})
            log_records.append(record)
        except json.JSONDecodeError as e:
            record = logging.makeLogRecord({'levelno': logging.ERROR,'msg': f"Error parsing file {filename}: {e}"})
            log_records.append(record)

    return config_dict, log_records

