            control_args[arg] = value
        elif arg.startswith('custom_'):
            nested_args[arg[len('custom_'):]] = value
        else:
            nested_args[arg] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        extra_vars = []
    for var in extra_vars:
        key, value = var.split('=')
        vars_dict[key] = value
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    import subprocess

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join([f"{k}={v}" for k, v in extra_vars.items()])
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is not None:
                command.extend([arg, str(value)])
            else:
                command.append(arg)

    result = subprocess.run(command, capture_output=True, text=True)
    return result.stdout, result.stderr, result.returncode

def _convert_non_cli_args(self, parser_name, values_dict):
    import ast
    type_map = {
        'int': int,
        'float': float,
        'bool': lambda x: x.lower() in ['true', '1', 't'],
        'list': ast.literal_eval,
        'dict': ast.literal_eval
    }
    config_path = f'config/{parser_name}_types.json'
    try:
        with open(config_path, 'r') as file:
            types = json.load(file)
    except FileNotFoundError:
        return

    for key, value in values_dict.items():
        if key in types:
            try:
                values_dict[key] = type_map[types[key]](value)
            except (ValueError, SyntaxError):
                pass

import os
import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    result = {}
    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.yaml') or file.endswith('.yml'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    data = yaml.safe_load(f)
                    flatten_dict(data, result, '')
    return result

def flatten_dict(d, result, parent_key):
    for k, v in d.items():
        new_key = f"{parent_key}.{k}" if parent_key else k
        if isinstance(v, dict):
            flatten_dict(v, result, new_key)
        else:
            result[new_key] = v

