def get_nodeinfo_well_known_document(url, document_path=None):
    import requests
    from urllib.parse import urljoin

    well_known_url = urljoin(url, '.well-known/nodeinfo')
    response = requests.get(well_known_url)
    response.raise_for_status()
    nodeinfo_links = response.json().get('links', [])

    nodeinfo_data = {}
    for link in nodeinfo_links:
        href = link.get('href')
        if href:
            nodeinfo_response = requests.get(href)
            nodeinfo_response.raise_for_status()
            nodeinfo_data[href] = nodeinfo_response.json()

    return {
        'url': url,
        'document_path': document_path,
        'well_known_url': well_known_url,
        'nodeinfo_data': nodeinfo_data
    }

